import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.B8HA7oqK.js";var c=JSON.parse(`{"title":"Fallback 回落","description":"","frontmatter":{},"headers":[],"relativePath":"config/features/fallback.md","filePath":"config/features/fallback.md","lastUpdated":1779716251000}`),l={name:`config/features/fallback.md`},u={id:`fallbacks-设计理论`,tabindex:`-1`};function d(a,c,l,d,f,p){let m=e(`Badge`);return s(),n(`div`,null,[c[3]||=t(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /config/features/fallback.md for this page in Markdown format</div><h1 id="fallback-回落" tabindex="-1">Fallback 回落 <a class="header-anchor" href="#fallback-回落" aria-label="Permalink to “Fallback 回落”">​</a></h1><blockquote><p><strong>Fallback 是 Xray 的最强大功能之一, 可有效防止主动探测, 自由配置常用端口多服务共享</strong></p></blockquote><p>fallback 为 Xray 提供了高强度的防主动探测性, 并且具有独创的首包回落机制.</p><p>fallback 也可以将不同类型的流量根据 path 进行分流, 从而实现一个端口, 多种服务共享.</p><p>目前您可以在使用 VLESS 或者 trojan 协议时, 通过配置 fallbacks 来使用回落这一特性, 并且创造出非常丰富的组合玩法.</p><h2 id="fallbacks-配置" tabindex="-1">fallbacks 配置 <a class="header-anchor" href="#fallbacks-配置" aria-label="Permalink to “fallbacks 配置”">​</a></h2><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;fallbacks&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: [</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    {</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">      &quot;dest&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">80</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">    }</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">  ]</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p><code>fallbacks</code>: [ <a href="#fallbackobject">FallbackObject</a> ]</p></blockquote><p>一个数组，包含一系列强大的回落分流配置。</p><h3 id="fallbackobject" tabindex="-1">FallbackObject <a class="header-anchor" href="#fallbackobject" aria-label="Permalink to “FallbackObject”">​</a></h3><div class="language-json line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">{</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;name&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;alpn&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;path&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;">&quot;&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;dest&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">80</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">,</span></span>
<span class="line"><span style="--shiki-dark:#9CDCFE;--shiki-light:#0451A5;">  &quot;xver&quot;</span><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">: </span><span style="--shiki-dark:#B5CEA8;--shiki-light:#098658;">0</span></span>
<span class="line"><span style="--shiki-dark:#D4D4D4;--shiki-light:#000000;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong><code>fallbacks</code> 是一个数组，这里是其中一个子元素的配置说明。</strong></p><p><code>fallbacks</code> 项是可选的，只能用于 TCP+TLS 传输组合</p><ul><li>该项有子元素时，<a href="./../transports/tls.html#tlsobject">Inbound TLS</a> 需设置 <code>&quot;alpn&quot;:[&quot;http/1.1&quot;]</code>。**</li></ul><p>通常，你需要先设置一组 <code>alpn</code> 和 <code>path</code> 均省略或为空的默认回落，然后再按需配置其它分流。</p><p>VLESS 会把 TLS 解密后首包长度 &lt; 18 或协议版本无效、身份认证失败的流量转发到 <code>dest</code> 指定的地址。</p><p>其它传输组合必须删掉 <code>fallbacks</code> 项或所有子元素，此时也不会开启 Fallback，VLESS 会等待读够所需长度，协议版本无效或身份认证失败时，将直接断开连接。</p><blockquote><p><code>name</code>: string</p></blockquote><p>尝试匹配 TLS SNI(Server Name Indication)，空为任意，默认为 &quot;&quot;</p><blockquote><p><code>alpn</code>: string</p></blockquote><p>尝试匹配 TLS ALPN 协商结果，空为任意，默认为 &quot;&quot;</p><p>有需要时，VLESS 才会尝试读取 TLS ALPN 协商结果，若成功，输出 info <code>realAlpn =</code> 到日志。 用途：解决了 Nginx 的 h2c 服务不能同时兼容 http/1.1 的问题，Nginx 需要写两行 listen，分别用于 1.1 和 h2c。 注意：fallbacks alpn 存在 <code>&quot;h2&quot;</code> 时，<a href="./../transports/tls.html#tlsobject">Inbound TLS</a> 需设置 <code>&quot;alpn&quot;:[&quot;h2&quot;,&quot;http/1.1&quot;]</code>，以支持 h2 访问。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Fallback 内设置的 <code>alpn</code> 是匹配实际协商出的 ALPN，而 Inbound TLS 设置的 <code>alpn</code> 是握手时可选的 ALPN 列表，两者含义不同。</p></div><blockquote><p><code>path</code>: string</p></blockquote><p>尝试匹配首包 HTTP PATH，空为任意，默认为空，非空则必须以 <code>/</code> 开头，不支持 h2c。</p><p>智能：有需要时，VLESS 才会尝试看一眼 PATH（不超过 55 个字节；最快算法，并不完整解析 HTTP），若成功，输出 INFO 日志 <code>realPath =</code>。 用途：分流其它 inbound 的 WebSocket 流量或 HTTP 伪装流量，没有多余处理、纯粹转发流量，理论性能比 Nginx 更强。</p><p>注意：<strong>fallbacks 所在入站本身必须是 TCP+TLS</strong>，这是分流至其它 WS 入站用的，被分流的入站则无需配置 TLS。</p><blockquote><p><code>dest</code>: string | number</p></blockquote><p>决定 TLS 解密后 TCP 流量的去向，目前支持两类地址：（该项必填，否则无法启动）</p><ol><li>TCP，格式为 <code>&quot;addr:port&quot;</code>，其中 addr 支持 IPv4、域名、IPv6，若填写域名，也将直接发起 TCP 连接（而不走内置的 DNS）。</li><li>Unix domain socket，格式为绝对路径，形如 <code>&quot;/dev/shm/domain.socket&quot;</code>，可在开头加 <code>@</code> 代表 <a href="https://www.man7.org/linux/man-pages/man7/unix.7.html" target="_blank" rel="noreferrer">abstract</a>，<code>@@</code> 则代表带 padding 的 abstract。</li></ol><p>若只填 port，数字或字符串均可，形如 <code>80</code>、<code>&quot;80&quot;</code>，通常指向一个明文 http 服务（addr 会被补为 <code>&quot;localhost&quot;</code>）。</p><p>注：v25.7.26 后才将只包含 port 的 dest 指向 localhost, 在此之前都是 127.0.0.1. 修改后实际目标很可能是 ::1 网上抄的部分模板的 webserver 可能也监听 ::1 的同时却只允许 127 进入或者应用 proxy protocol，这可能会导致行为不同。</p><blockquote><p><code>xver</code>: number</p></blockquote><p>发送 <a href="https://www.haproxy.org/download/2.2/doc/proxy-protocol.txt" target="_blank" rel="noreferrer">PROXY protocol</a>，专用于传递请求的真实来源 IP 和端口，填版本 1 或 2，默认为 0，即不发送。若有需要建议填 1。</p><p>目前填 1 或 2，功能完全相同，只是结构不同，且前者可打印，后者为二进制。Xray 的 TCP 和 WS 入站均已支持接收 PROXY protocol。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>若你正在 <a href="https://docs.nginx.com/nginx/admin-guide/load-balancer/using-proxy-protocol/#configuring-nginx-to-accept-the-proxy-protocol" target="_blank" rel="noreferrer">配置 Nginx 接收 PROXY protocol</a>，除了设置 proxy_protocol 外，还需设置 set_real_ip_from，否则可能会出问题。</p></div><h3 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to “补充说明”">​</a></h3><ul><li>将匹配到最精确的子元素，与子元素的排列顺序无关。若配置了几个 alpn 和 path 均相同的子元素，则会以最后的为准。</li><li>回落分流均是解密后 TCP 层的转发，而不是 HTTP 层，只在必要时检查首包 PATH。</li><li>您可以查看更多的关于 Fallbacks 的使用技巧和心得 <ul><li><a href="./../../document/level-1/fallbacks-lv1.html">Fallbacks 功能简析</a></li></ul></li></ul>`,39),o(`h2`,u,[c[0]||=r(`Fallbacks 设计理论 `,-1),i(m,{text:`WIP`,type:`warning`}),c[1]||=r(),c[2]||=o(`a`,{class:`header-anchor`,href:`#fallbacks-设计理论`,"aria-label":`Permalink to “Fallbacks 设计理论”`},`​`,-1)])])}var f=a(l,[[`render`,d]]);export{c as __pageData,f as default};